function handleSelectChange(selectEl, type) {
    if (selectEl.value === 'ADD_NEW') {
        Swal.fire({
            title: type === 'company' ? 'أدخل اسم الشركة الجديدة' : (type === 'dest' ? 'أدخل الموقع الجديد' : 'أدخل اسم القسم الجديد'),
            input: 'text',
            showCancelButton: true,
            confirmButtonText: 'إضافة',
            cancelButtonText: 'إلغاء',
            customClass: {
                container: 'high-z-index-swal'
            },
            didOpen: () => {
                // Force the SweetAlert popup to be above all modals!
                document.querySelector('.high-z-index-swal').style.setProperty('z-index', '999999', 'important');
            }
        }).then((result) => {
            if (result.isConfirmed && result.value.trim() !== '') {
                const newVal = result.value.trim();
                if (type === 'company') {
                    customCompanies.add(newVal);
                } else if (type === 'dest') {
                    customDestinations.add(newVal);
                } else {
                    customDepartments.add(newVal);
                }
                // Re-render the dropdowns immediately so the option appears natively across the app
                populateCompanyAndDestDropdowns();
                // Auto-select the newly added value
                selectEl.value = newVal;
            } else {
                selectEl.value = '';
            }
        });
    }
}

