function openExceptionModal() {
    if (!selectedEmployeeId) {
        Swal.fire('Error', 'Please select an employee first.', 'error');
        return;
    }
    document.getElementById('excStart').value = '';
    document.getElementById('excEnd').value = '';
    document.getElementById('excReplacementId').value = '';
    document.getElementById('excNotes').value = '';
    document.getElementById('coverSuggestions').innerHTML = '';
    document.getElementById('exceptionModal').style.display = 'block';
}

function suggestReplacements() {
    const startStr = document.getElementById('excStart').value;
    const endStr = document.getElementById('excEnd').value;
    const suggestionsDiv = document.getElementById('coverSuggestions');
    suggestionsDiv.innerHTML = '';

    if (!startStr || !endStr || !selectedEmployeeId) return;

    const emp = employees.find(e => String(e.ID) === String(selectedEmployeeId));
    if (!emp || !emp.Department) return;

    const startNum = parseDate(startStr).getTime();
    const endNum = parseDate(endStr).getTime();
    if (startNum > endNum) return;

    let availableCovers = [];

    employees.forEach(e => {
        if (e.ID === emp.ID) return;
        if (e.Department !== emp.Department) return; // Must be same department

        let coversFully = false;
        if (e.Rotations) {
            e.Rotations.forEach(r => {
                if (r.type === 'leave' || r.type === 'rest') {
                    const rStart = parseDate(r.start).getTime();
                    const rEnd = parseDate(r.end).getTime();
                    if (rStart <= startNum && rEnd >= endNum) {
                        coversFully = true;
                    }
                }
            });
        }

        let hasConflictOverride = false;
        if (e.Overrides) {
            e.Overrides.forEach(ov => {
                const oStart = parseDate(ov.start).getTime();
                const oEnd = parseDate(ov.end).getTime();
                if (oStart <= endNum && oEnd >= startNum) {
                    hasConflictOverride = true;
                }
            });
        }

        if (coversFully && !hasConflictOverride) {
            availableCovers.push(e);
        }
    });

    if (availableCovers.length > 0) {
        let html = '<div style="width: 100%; font-size: 11px; color: #10b981; margin-bottom: 4px;">✨ Smart Suggestions (Colleagues on Leave):</div>';
        availableCovers.forEach(c => {
            html += `<span onclick="document.getElementById('excReplacementId').value = '${c.ID}';" style="cursor:pointer; background: rgba(16,185,129,0.1); color: #10b981; border: 1px solid rgba(16,185,129,0.3); padding: 4px 10px; border-radius: 20px; font-size: 11px; transition: all 0.2s;" onmouseover="this.style.background='rgba(16,185,129,0.2)'" onmouseout="this.style.background='rgba(16,185,129,0.1)'" title="Select ${c.Name}">👤 ${c.Name} (${c.ID})</span>`;
        });
        suggestionsDiv.innerHTML = html;
    } else {
        suggestionsDiv.innerHTML = '<div style="width: 100%; font-size: 11px; color: #94a3b8;">No matching colleagues found on leave in this department.</div>';
    }
}

