function directExportPDF() {
    if (typeof Swal !== 'undefined') {
        Swal.fire({
            title: 'Generating PDF...',
            text: 'Please wait while we prepare your professional report.',
            icon: 'info',
            allowOutsideClick: false,
            didOpen: () => { Swal.showLoading(); }
        });
    }

    let html = `
        <table style="width: 100%; border-collapse: collapse; margin-top: 10px; font-size: 11px;">
            <thead>
                <tr>
                    <th style="border: 1px solid #cbd5e1; padding: 8px; text-align: center; background-color: #f1f5f9; font-weight: bold; color: #1e293b;">#</th>
                    <th style="border: 1px solid #cbd5e1; padding: 8px; text-align: center; background-color: #f1f5f9; font-weight: bold; color: #1e293b;">ID</th>
                    <th style="border: 1px solid #cbd5e1; padding: 8px; text-align: left; background-color: #f1f5f9; font-weight: bold; color: #1e293b;">Name</th>
                    <th style="border: 1px solid #cbd5e1; padding: 8px; text-align: center; background-color: #f1f5f9; font-weight: bold; color: #1e293b;">Company</th>
                    <th style="border: 1px solid #cbd5e1; padding: 8px; text-align: center; background-color: #f1f5f9; font-weight: bold; color: #1e293b;">Destination</th>
                    <th style="border: 1px solid #cbd5e1; padding: 8px; text-align: center; background-color: #f1f5f9; font-weight: bold; color: #1e293b;">Phone</th>
                    <th style="border: 1px solid #cbd5e1; padding: 8px; text-align: center; background-color: #f1f5f9; font-weight: bold; color: #1e293b;">Work (Days)</th>
                    <th style="border: 1px solid #cbd5e1; padding: 8px; text-align: center; background-color: #f1f5f9; font-weight: bold; color: #1e293b;">Leave (Days)</th>
                </tr>
            </thead>
            <tbody>
    `;

    let displayList = filteredEmployees.map(e => {
        let totalWork = 0, totalLeave = 0;
        if (e.Rotations) {
            e.Rotations.forEach(r => {
                const days = Math.floor((parseDate(r.end).getTime() - parseDate(r.start).getTime()) / (1000 * 3600 * 24)) + 1;
                if (r.type === 'work' || r.type === 'standby_cover') totalWork += days;
                if (r.type === 'leave' || r.type === 'rest') totalLeave += days;
            });
        }
        return { ...e, computedWork: totalWork, computedLeave: totalLeave };
    });

    displayList.forEach((e, idx) => {
        html += `<tr>
            <td style="border: 1px solid #cbd5e1; padding: 6px; text-align: center; color: #334155;">${idx + 1}</td>
            <td style="border: 1px solid #cbd5e1; padding: 6px; text-align: center; font-weight: bold; color: #0f172a;">${e.ID || '-'}</td>
            <td style="border: 1px solid #cbd5e1; padding: 6px; text-align: left; color: #334155;">
                <div style="font-weight: 600;">${e.Name || '-'}</div>
            </td>
            <td style="border: 1px solid #cbd5e1; padding: 6px; text-align: center; color: #334155;">${e.Company || '-'}</td>
            <td style="border: 1px solid #cbd5e1; padding: 6px; text-align: center; color: #334155;">${e.Destination || '-'}</td>
            <td style="border: 1px solid #cbd5e1; padding: 6px; text-align: center; color: #334155;">${e.Phone || '-'}</td>
            <td style="border: 1px solid #cbd5e1; padding: 6px; text-align: center; color: #10b981; font-weight: 600;">${e.computedWork}</td>
            <td style="border: 1px solid #cbd5e1; padding: 6px; text-align: center; color: #ef4444; font-weight: 600;">${e.computedLeave}</td>
        </tr>`;
    });
    html += `</tbody></table>`;

    const script = document.createElement('script');
    script.src = 'https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js';
    script.onload = () => {
        const tempDiv = document.createElement('div');
        tempDiv.innerHTML = `
            <div style="padding: 20px; background: white; color: black; font-family: 'Helvetica Neue', Helvetica, Arial, sans-serif;">
                <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 2px solid #e2e8f0; padding-bottom: 10px; margin-bottom: 15px;">
                    <h2 style="margin: 0; color: #1e293b; font-size: 20px; font-weight: 800;">🏢 HR-BLK53 Master Directory</h2>
                    <div style="text-align: right; font-size: 10px; color: #64748b;">
                        <div>Generated: ${new Date().toLocaleDateString('en-GB')}</div>
                        <div>Total Personnel: ${displayList.length}</div>
                    </div>
                </div>
                ${html}
            </div>
        `;

        const opt = {
            margin:       0.4,
            filename:     'HR_Master_Report_' + new Date().toISOString().split('T')[0] + '.pdf',
            image:        { type: 'jpeg', quality: 0.98 },
            html2canvas:  { scale: 2, useCORS: true },
            jsPDF:        { unit: 'in', format: 'a4', orientation: 'portrait' }
        };

        html2pdf().set(opt).from(tempDiv).save().then(() => {
            if (typeof Swal !== 'undefined') Swal.close();
        });
    };
    script.onerror = () => {
        if (typeof Swal !== 'undefined') {
            Swal.fire('Error', 'Failed to load PDF engine. Check your internet connection.', 'error');
        }
    };
    document.head.appendChild(script);
}

